<template>
  <div class="step_container">
    <div class="itemsArea">
      <!-- 파일 업로드 토글 -->

      <v-row class="mb-3">
        <v-col cols="12">
          <v-btn-toggle
            v-model="uploadMode"
            mandatory
            class="btn-toggle-full custom-toggle"
          >
            <v-btn value="manual">직접 설정</v-btn>
            <v-btn value="file">파일 업로드</v-btn>
          </v-btn-toggle>
        </v-col>
      </v-row>

      <!-- ✅ Native Drop 영역 -->
      <div v-show="uploadMode === 'file'" class="upload-wrapper">
        <div
          ref="nativeDropZone"
          class="native-drop-zone"
          @click="triggerNativeFile"
          @dragover.prevent="dragging = true"
          @dragleave.prevent="dragging = false"
          @drop.prevent="onNativeDrop"
          :class="{ active: dragging }"
        >
          <!-- ✅ 파일명 / 안내문구 교체 -->
          <template v-if="fileName">
            <div class="file-display">
              <v-icon color="primary" size="20">mdi-file</v-icon>
              <span class="ml-2"> {{ fileName }} ({{ fileSize }}) </span>
              <v-btn
                icon
                variant="text"
                color="error"
                size="x-small"
                class="ml-1"
                @click.stop="clearFile"
              >
                <v-icon size="16">mdi-close</v-icon>
              </v-btn>
            </div>
          </template>

          <template v-else>
            <p>
              📂 파일을 이 영역으로 <strong>끌어오거나</strong><br />클릭해서
              선택하세요
            </p>
          </template>

          <!-- 숨김 input -->
          <input
            ref="nativeFileInput"
            type="file"
            accept=".csv,.xlsx,.txt, .json"
            style="display: none"
            @change="onNativeFileChange"
          />
        </div>
      </div>

      <div :class="['gray-panel', { disabled: uploadMode === 'file' }]">
        <v-row>
          <v-col>
            <v-card class="demandArea">
              <v-card-title>수요지역</v-card-title>
              <v-card-text>
                <v-text-field
                  label="주소 검색"
                  variant="outlined"
                  v-model="demandArea"
                  placeholder="주소를 검색하세요"
                  readonly
                  prepend-inner-icon="mdi-magnify"
                  @click="openPostcode"
                  color="primary"
                  class="mb-3"
                  hide-details
                />
                <v-btn class="round Item" @click="addDemandArea"> 추가 </v-btn>
                <!-- 
              <v-text-field
                label="용량"
                type="number"
                variant="outlined"
                v-model="electricCapacity"
                prepend-inner-icon="mdi-lightning-bolt"
                color="primary"
                class="mb-3"
                hide-details
              >
                <template #append-inner>
                  <span class="text-subtitle-2 pr-2">MW</span>
                </template>
              </v-text-field>

              <v-text-field
                label="일별 전력 사용시간"
                type="number"
                variant="outlined"
                v-model="hoursPerDay"
                prepend-inner-icon="mdi-hours-24"
                color="primary"
                @update:model-value = 'validateHoursPerDay'
              >
                <template #append-inner>
                  <span class="text-subtitle-2 pr-2">hr/day</span>
                </template>
              </v-text-field> -->
              </v-card-text>
            </v-card>
          </v-col>
        </v-row>

        <v-row>
          <v-col>
            <v-card>
              <v-card-title>송배전망</v-card-title>
              <div class="buttons">
                <v-btn
                  class="round Item"
                  v-for="btn in transStore"
                  :key="btn.id"
                  draggable="true"
                  @dragstart="startDrag($event, btn)"
                >
                  {{ btn.label }}
                </v-btn>
              </div>
              <v-divider></v-divider>
              <div class="buttons">
                <v-btn
                  class="round Item"
                  v-for="btn in distribStore"
                  :key="btn.id"
                  draggable="true"
                  @dragstart="startDrag($event, btn)"
                >
                  {{ btn.label }}
                </v-btn>
              </div>
            </v-card>
          </v-col>
        </v-row>

        <v-row>
          <v-col>
            <v-card>
              <v-card-title>NWAs</v-card-title>
              <div class="buttons nwas">
                <v-btn
                  class="round Item"
                  v-for="btn in nwasStore"
                  :key="btn.id"
                  draggable="true"
                  @dragstart="startDrag($event, btn)"
                >
                  {{ btn.label }}
                </v-btn>
              </div>
            </v-card>
          </v-col>
        </v-row>

        <v-row>
          <v-col>
            <v-card class="cntTopology">
              <v-card-title>Topology</v-card-title>
              <v-card-text class="mt-3">
                <p class="text-body-1">
                  <strong>최대구성 :</strong> {{ maxTopology }} 개
                </p>
              </v-card-text>
            </v-card>
          </v-col>
        </v-row>
      </div>
    </div>

    <div class="arrangeArea">
      <div class="drop-zones">
        <div
          v-for="zone in dropZones"
          :key="zone.id"
          class="drop-zone"
          :class="{ 'invalid-zone': !zone.isValid }"
          @dragover="onDragOver($event, zone.id)"
          @dragleave="resetZoneColors"
          @drop="onDrop($event, zone.id)"
        >
          <h3>{{ zone.name }}</h3>
          <ul class="list-unstyled m-0 p-0">
            <li v-for="item in zone.items" :key="item.id">
              <div
                class="round Item"
                @contextmenu.prevent="removeItem(zone.id, item.uniqueId)"
              >
                <div
                  class="header"
                  :class="{ 'blue-header': item.setProperty }"
                >
                  {{ item.label }}
                </div>

                <div class="content">
                  <button
                    class="childButton"
                    :class="{ 'gray-button': item.id === 1 }"
                    @click="openDialog(item.id, item.uniqueId, item.label)"
                  >
                    세부설정
                  </button>
                </div>
              </div>
            </li>
          </ul>
        </div>
      </div>

      <div class="step-controls">
        <v-btn class="step-button" @click="goToNextStep"> 확인 </v-btn>
      </div>
    </div>
  </div>

  <v-dialog v-model="showDialog" max-width="400px">
    <v-card>
      <v-card-title> 알림 </v-card-title>
      <v-card-text> {{ dialogText }} </v-card-text>
      <v-card-actions>
        <v-btn color="primary" @click="showDialog = false">닫기</v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>

  <div v-if="isLoading" class="loading-overlay">
  <div class="spinner"></div>
  <p>파일을 불러오는 중입니다…</p>
</div>

</template>


<script setup>
import { ref, watch, defineEmits } from "vue";
import { useDropZoneStore } from "../store/dropZoneStore.js";
import { useItemStore } from "../store/itemStore.js";
import { useProgressStore } from "../store/progressStore.js";
import { useTopologyStore } from "../store/topologyStore.js";
import { storeToRefs } from "pinia";
import { useRouter } from "vue-router";

const store = useDropZoneStore();
const topologyStore = useTopologyStore();

const { dropZones } = storeToRefs(store);

const itemStore = useItemStore();
const { transStore } = storeToRefs(itemStore);
const { distribStore } = storeToRefs(itemStore);
const { nwasStore } = storeToRefs(itemStore);

const startItem = ref(null);
const maxTopology = ref(0);

const progressStore = useProgressStore();
const router = useRouter();
const demandArea = ref("");

var dialogText = ref("");
const showDialog = ref(false);

const uploadMode = ref("manual");
const nativeFileInput = ref(null);
const nativeDropZone = ref(null);
const dragging = ref(false);
const fileName = ref("");
const fileSize = ref("");

const isLoading = ref(false);

// 파일 클릭
function triggerNativeFile() {
  if (nativeFileInput.value) {
    nativeFileInput.value.value = "";
    nativeFileInput.value.click();
  }
}

// 파일 변경 이벤트
function onNativeFileChange(e) {
  const file = e.target.files?.[0];
  if (file) handleNativeFile(file);
}

// 파일 드롭 이벤트
function onNativeDrop(e) {
  dragging.value = false;
  const file = e.dataTransfer?.files?.[0];
  if (file) handleNativeFile(file);
}

async function handleNativeFile(file) {
  fileName.value = file.name;
  fileSize.value = formatSize(file.size);

  const dropZoneStore = useDropZoneStore();

  try {
    isLoading.value = true; // 🔥 로딩 시작

    const content = await readFileContent(file);
    const clean = content.replace(/^\uFEFF/, "");

    let parsed;
    try {
      parsed = JSON.parse(clean);
    } catch (e) {
      console.error("JSON 파싱 실패:", e);
      return;
    }

    if (!Array.isArray(parsed)) {
      console.error("업로드된 JSON은 배열이 아닙니다:", parsed);
      return;
    }

    // 1️⃣ 좌표 보정
    const enrichedTopology = await enrichTopologyWithCoordinates(parsed);

    // 2️⃣ topologyStore 업데이트
    topologyStore.topologyList = enrichedTopology;

    // 3️⃣ DropZone 변환
    const dz = convertTopologyToDropZone(enrichedTopology);
    dropZoneStore.dropZones = dz;

    console.log("DropZoneStore 업데이트 완료:", dz);

    // 4️⃣ step 조건 세팅
    progressStore.setStepCondition("step1", true);
    progressStore.setStepCondition("step2", true);
    progressStore.setStepCondition("step3", true);

    // ✅ UX를 위한 짧은 대기 (선택)
    await new Promise(res => setTimeout(res, 300));

    // 5️⃣ step4 이동
    router.push("/step4");

  } catch (err) {
    console.error("❌ 파일 읽기 오류:", err);
  } finally {
    isLoading.value = false; // 🔥 로딩 종료
  }
}

// X버튼 초기화
function clearFile() {
  fileName.value = "";
  fileSize.value = "";
  if (nativeFileInput.value) nativeFileInput.value.value = "";
}

// 파일 크기 표시
function formatSize(size) {
  const kb = size / 1024;
  return kb < 1024 ? `${kb.toFixed(1)} KB` : `${(kb / 1024).toFixed(1)} MB`;
}

function readFileContent(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    // CSV, JSON, TXT → 문자열로 읽기
    if (file.name.endsWith(".csv") ||
        file.name.endsWith(".txt") ||
        file.name.endsWith(".json")) {
      reader.readAsText(file, "utf-8");
    }
    // XLSX → ArrayBuffer 필요
    else if (file.name.endsWith(".xlsx")) {
      reader.readAsArrayBuffer(file);
    }
    else {
      reject("지원하지 않는 파일 형식입니다.");
      return;
    }

    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error);
  });
}

function convertTopologyToDropZone(topologyList) {
  const dropZones = [
    { id: 1, name: "발전소", items: [], isValid: true },
    { id: 2, name: "765kV", items: [], isValid: true },
    { id: 3, name: "345kV", items: [], isValid: true },
    { id: 4, name: "154kV", items: [], isValid: true },
    { id: 5, name: "22.9kV", items: [], isValid: true },
    { id: 6, name: "수요지역", items: [], isValid: true },
    { id: 7, name: "NWAs", items: [], isValid: true },
  ];

  // topologyList = [ [items...], [items...] ... ]
  topologyList.forEach(group => {
    if (!Array.isArray(group)) return;

    group.forEach(item => {
      if (!item || item.id == null) return;

      const zone = dropZones.find(z => z.id === Number(item.id));
      if (!zone) return;

      // DropZone용 복사본
      zone.items.push({ ...item });
    });
  });

  // 🔥 각 zone 별로 label 기준 중복 제거
  dropZones.forEach(zone => {
    zone.items = zone.items.filter(
      (item, index, self) =>
        index === self.findIndex(i => i.label === item.label)
    );
  });

  return dropZones;
}


async function enrichTopologyWithCoordinates(topologyList) {
  for (const group of topologyList) {
    if (!Array.isArray(group)) continue;

    for (const item of group) {
      if (!item || item.id !== 6) continue; // 수요지역만

      if (item.lat !== 0 && item.lng !== 0) continue;

      const address = item.property
        ?.find(p => p.name === "수요지역정보")
        ?.values?.find(v => v.name === "주소")
        ?.data;

      if (!address) continue;

      try {
        const { lat, lng } = await getCoordinatesFromAddress(address);
        item.lat = lat;
        item.lng = lng;
      } catch (e) {
        console.warn("수요지역 위경도 변환 실패:", address, e);
      }
    }
  }

  return topologyList;
}

const getCoordinatesFromAddress = (address) => {

  return new Promise((resolve, reject) => {
    let geocoder = new window.google.maps.Geocoder();

    geocoder.geocode({ address }, (results, status) => {
      if (status === "OK" && results[0]) {
        const location = results[0].geometry.location;
        resolve({ lat: location.lat(), lng: location.lng() });
        console.log("lat : ", location.lat(), "lan : ", location.lng())
      } else {
        reject(status);
      }
    });
  });
};



const emit = defineEmits(["openDialog"]);

const openDialog = (id, uniqueId, label) => {
  emit("openDialog", id, uniqueId, label);
};

// 주소검색
const openPostcode = () => {
  new window.daum.Postcode({
    oncomplete: function (data) {
      demandArea.value = data.address;
    },
  }).open();
};

// 드래그 시작 시 실행
const startDrag = (event, item) => {
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData("draggedItem", JSON.stringify(item));
  startItem.value = item;
};

// 아이템 배치완료
const onDrop = (event, zoneId) => {
  const draggedItem = JSON.parse(event.dataTransfer.getData("draggedItem"));

  store.addItemToZone(zoneId, draggedItem);
  resetZoneColors();
  startItem.value = null;
};

// 해당 열 확인
const onDragOver = (event, zoneId) => {
  event.preventDefault();

  if (!startItem.value) return;

  const isValid = zoneId === startItem.value.id;

  event.dataTransfer.dropEffect = isValid ? "move" : "none";

  dropZones.value.forEach((zone) => {
    zone.isValid = zone.id === startItem.value.id;
  });
};

const resetZoneColors = () => {
  dropZones.value.forEach((zone) => (zone.isValid = true));
};

// function validateHoursPerDay(value){
//   if (value > 24){
//     dialogText = "일별 전력 사용시간은 최대 24시간까지 입력가능합니다.";
//     showDialog.value = true;
//     hoursPerDay.value = ref('')
//   }
// }

const addDemandArea = () => {
  const result = store.saveDemandArea(demandArea);
  if (result === "exists") {
    dialogText = "이미 등록된 주소입니다.";
    showDialog.value = true;
  }
};

// 모든 dropzone에 하나 이상의 값이 저장되었을 때
watch(
  dropZones,
  (newZones) => {
    //  765(Zone ID: 2)를 제외한 모든 Zone이 비어있지 않은지 확인
    const relevantZones = newZones.filter((zone) => zone.id !== 2);

    const allFilled = relevantZones.every((zone) => zone.items.length > 0);

    if (allFilled) {
      //  maxTopology = (765 포함) 모든 zone의 items 개수 곱하기
      maxTopology.value = newZones.reduce(
        (product, zone) => product * (zone.items.length || 1), //  비어있는 zone은 1로 처리
        1
      );
    } else {
      maxTopology.value = 0;
    }
  },
  { deep: true, immediate: true }
);

const removeItem = (zoneId, uniqueId) => {
  store.removeItemFromZone(zoneId, uniqueId);
  topologyStore.clearTopologyList();
};

// 완료 조건 함수
const isStep1Completed = () => {
  // 1. DropZoneStore에서 수요지역 데이터 가져오기 (ID 6)
  const demandZone = dropZones.value.find((zone) => zone.id === 6);
  const hasDemandData = demandZone?.items?.length > 0; // 안전한 데이터 접근 방식

  if (!hasDemandData) {
    dialogText = "수요지역 위치와 용량을 입력하세요.";
    showDialog.value = true;
    return false;
  }

  // 2. 765를 제외한 모든 dropZone이 비어있지 않은지 확인
  const relevantZones = dropZones.value.filter((zone) => zone.id !== 2);
  const allFilled = relevantZones.every((zone) => zone.items.length > 0);

  if (!allFilled) {
    dialogText = "모든 DropZone에 아이템을 배치해야 합니다. (765 제외)";
    showDialog.value = true;
    return false;
  }

  return true; // 모든 조건을 충족하면 true 반환
};

// "다음" 버튼 클릭 시 완료 검사 + 이동
const goToNextStep = () => {
  if (isStep1Completed()) {
    // 완료 조건 검사
    progressStore.setStepCondition("step1", true); // Step1 완료 상태 저장
    router.push("/step2"); // Step2로 이동
    console.log("step1 DropZones : ", JSON.stringify(dropZones.value));
  } else {
    progressStore.setStepCondition("step1", false); // Step1 완료 상태 저장
  }
};
</script>


<style lang="scss" scoped>
.step_container {
  display: flex;
}

#daumLocation {
  margin-left: 16px;
  background: rgb(var(--dark-alt));
  border: none;
  border-radius: 2px;
  padding: 4px 8px;
  color: white;
  font-size: 14px;
  font-weight: bold;
}

.v-btn-toggle .v-btn {
  width: 48%;
}

.gray-panel.disabled {
  opacity: 0.5;
  pointer-events: none;
  transition: 0.3s;
}

.gray-panel {
  transition: 0.3s;
}

.upload-wrapper {
  margin-top: 10px;
}

.native-drop-zone {
  border: 2px dashed #90caf9;
  border-radius: 12px;
  padding: 50px;
  text-align: center;
  cursor: pointer;
  transition: 0.3s;
  background: #fafafa;
}

.native-drop-zone.active {
  background: #e3f2fd;
  border-color: #1976d2;
}

/* ✅ 파일명 영역 스타일 */
.file-display {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  font-size: 1.2rem;
  color: #333;
}

/* X 버튼 작게 */
.v-btn--size-x-small {
  height: 20px !important;
  width: 20px !important;
  min-width: 20px !important;
  padding: 0 !important;
}

.gray-panel.disabled {
  opacity: 0.4;
  pointer-events: none;
}

.btn-toggle-full {
  display: flex;
  width: 100%;
}

.btn-toggle-full .v-btn {
  flex: 1; /* 두 버튼이 동일 비율로 가로 꽉 채움 */
  justify-content: center;
  font-weight: 500;
}

.custom-toggle .v-btn.v-btn--active {
  background-color: #063480 !important;
  color: white !important;
}

.loading-overlay {
  position: fixed;
  inset: 0;
  background: rgba(255, 255, 255, 0.7);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 9999;
}

.spinner {
  width: 48px;
  height: 48px;
  border: 4px solid #ddd;
  border-top: 4px solid #063480;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}
</style>